window.TI_CHAPTER_DATA["chapter3"] = {"chapter":{"id":3,"title":"Глава 3. Россия","shortTitle":"Глава 3","grade":"8 класс","startSector":"sector-27","requiresChapter":null,"mission":"Миссия: составить паспорт России — понять, как формировалась территория страны, какова её природа и как живут люди в разных её частях.","knownFacts":["Россия — самая большая страна мира: её площадь около 17,1 млн км².","Север на схемах вверху, восток справа. Карта России схематична: границы и очертания упрощены, масштаб не соблюдается."],"topics":{"history":"История освоения","borders":"Положение и границы","timezones":"Время на территории России","regions":"Районирование","resources":"Природные ресурсы","geology":"Рельеф и строение","climate_ru":"Климат России","waters_ru":"Моря и внутренние воды","zones":"Природные зоны","safety":"Безопасность и охрана природы","population_ru":"Численность населения","settlement":"Размещение населения","peoples_ru":"Народы и религии","capital":"Человеческий капитал"},"intro":{"title":"Глава 3. Паспорт России","paragraphs":["Земля исследована, и научный совет ставит новую задачу: составить подробный паспорт страны, в которой вы живёте. Законы природы вы уже знаете, теперь нужно увидеть, как они проявляются на территории России.","Орбитальный сканер выводит схему страны: её историю, границы, природу и население. Карта упрощена, но все данные настоящие.","Начните с первых землепроходцев и дойдите до жителей сегодняшней России. Можно ошибаться, читать подсказки и пробовать снова."],"button":"Начать главу 3"},"finale":{"title":"Паспорт России составлен","paragraphs":["Все 14 зон карты России исследованы. Теперь видно, как связаны история и положение страны, рельеф и климат, моря и реки, природные зоны и расселение людей.","Огромная территория, разнообразная природа и многонациональное население делают Россию страной больших возможностей и больших ответственностей: природные богатства нужно использовать разумно, а регионы развивать вместе."]},"map":{"mapWidth":1100,"mapHeight":700,"caption":"Россия · схема орбитального сканирования (масштаб не соблюдается)","oceanLabel":null,"ariaLabel":"Карта России","compass":[70,45],"captionPos":[150,30],"routes":false,"backdrop":["70,330 110,260 170,220 230,170 300,140 400,120 520,95 660,80 800,70 930,80 1040,100 1085,170 1070,260 1080,340 1070,430 1020,490 900,510 800,500 700,520 600,515 500,510 400,525 300,530 200,500 120,430"]}},"sectors":[{"id":"sector-27","name":"Дороги первопроходцев","type":"hist","tint":"#d9b98a","chapter":3,"description":"Старые карты и записи землепроходцев показывают, как небольшое государство на западе за несколько веков стало самой большой страной мира. Нужно проследить этот путь.","geo":"Этапы освоения и формирования территории России: от Московской Руси до наших дней.","requires":[],"taskIds":["task-105","task-106","task-107","task-108"],"discoveries":["discovery-027"],"poly":"255,325 239,358 192,370 148,370 103,358 88,325 105,293 147,277 195,274 234,294","center":[170,325],"journal":"Исследованы «Дороги первопроходцев». Территория России росла веками: путь на восток через Урал и Сибирь к Тихому океану, выход к морям, потери и присоединения."},{"id":"sector-28","name":"Границы и моря","type":"borders","tint":"#9fc4dd","chapter":3,"description":"Спутник обводит контур страны: суша, лесные и горные рубежи, три океана. Нужно понять, где проходят границы и что омывает страну.","geo":"Крайние точки, соседи, государственная граница, моря, исключительная экономическая зона.","requires":["sector-27"],"taskIds":["task-109","task-110","task-111","task-112"],"discoveries":["discovery-028"],"poly":"376,190 360,215 324,233 277,231 241,215 222,190 230,161 274,144 326,144 361,164","center":[300,190],"journal":"Исследованы «Границы и моря». Россия граничит с 14 странами и омывается морями трёх океанов; ей принадлежат территориальные воды, исключительная экономическая зона и шельф."},{"id":"sector-29","name":"Часовые пояса","type":"time","tint":"#c9b9e0","chapter":3,"description":"Страна так велика, что на её восточной окраине уже наступает вечер, когда на западе ещё день. Нужно научиться определять разницу во времени.","geo":"Часовые зоны России, местное, поясное и зональное время.","requires":["sector-28"],"taskIds":["task-113","task-114","task-115","task-116"],"discoveries":["discovery-029"],"poly":"585,190 569,219 525,234 476,232 442,214 417,190 436,163 474,144 524,147 568,162","center":[500,190],"journal":"Исследованы «Часовые пояса». На территории России 11 часовых зон: разница между Калининградом и Камчаткой — 10 часов."},{"id":"sector-30","name":"Регионы страны","type":"regions","tint":"#b8d4a0","chapter":3,"description":"Россия — федерация: в её состав входят субъекты разных видов. Их объединяют в федеральные округа и районы. Нужно разобраться в этом устройстве.","geo":"Субъекты Российской Федерации, федеральные округа, районирование территории.","requires":["sector-28"],"taskIds":["task-117","task-118","task-119","task-120"],"discoveries":["discovery-030"],"poly":"436,320 431,352 383,364 334,370 301,347 284,320 289,288 337,275 385,271 424,291","center":[360,320],"journal":"Исследованы «Регионы страны». Субъекты РФ бывают разных видов и очень различаются площадью; для управления и изучения их объединяют в федеральные округа и районы."},{"id":"sector-31","name":"Природные ресурсы","type":"resources","tint":"#e0c070","chapter":3,"description":"Недра, леса, воды и земли — природный капитал страны. Данные разведки показывают, где он сосредоточен и как его используют.","geo":"Классификация природных ресурсов, ресурсные базы, рациональное природопользование.","requires":["sector-29","sector-30"],"taskIds":["task-121","task-122","task-123","task-124"],"discoveries":["discovery-031"],"poly":"321,450 304,478 265,496 217,493 171,480 155,450 173,421 217,407 265,404 302,423","center":[240,450],"journal":"Исследованы «Природные ресурсы». Ресурсы делят на исчерпаемые и неисчерпаемые; их использование должно быть рациональным, а не расточительным."},{"id":"sector-32","name":"Платформы и горы","type":"geology","tint":"#d4a68f","chapter":3,"description":"Сейсмодатчики и геологические карты показывают, на каких основаниях стоят равнины и горы России. Нужно понять, почему рельеф так разнообразен.","geo":"Платформы и плиты, области горообразования, формы рельефа и полезные ископаемые.","requires":["sector-31"],"taskIds":["task-125","task-126","task-127","task-128"],"discoveries":["discovery-032"],"poly":"640,320 627,350 586,369 537,364 502,347 482,320 498,292 534,269 586,271 626,290","center":[560,320],"journal":"Исследованы «Платформы и горы». Равнины лежат на платформах, горы — в областях складчатости; сильнее всего земная кора «живёт» на востоке страны."},{"id":"sector-33","name":"Климат и погода","type":"climate_ru","tint":"#bcd6ea","chapter":3,"description":"Метеостанции от Калининграда до Чукотки передают данные. Климат России меняется от умеренно-мягкого на западе до резкого на востоке.","geo":"Солнечная радиация, воздушные массы, циклоны и антициклоны, увлажнение, типы климата.","requires":["sector-31"],"taskIds":["task-129","task-130","task-131","task-132"],"discoveries":["discovery-033"],"poly":"774,190 767,218 725,235 673,238 638,216 624,190 632,162 674,145 724,148 767,162","center":[700,190],"journal":"Исследованы «Климат и погода». Климат России определяют широта, циркуляция атмосферы и удалённость от океанов; погоду объясняют циклоны и антициклоны."},{"id":"sector-34","name":"Моря, реки и озёра","type":"waters","tint":"#86bdd9","chapter":3,"description":"Спутник отслеживает водные пути: моря трёх океанов, огромные сибирские реки и самое глубокое озеро мира. Нужно сравнить водные объекты.","geo":"Моря России, крупные реки и озёра, их особенности.","requires":["sector-33"],"taskIds":["task-133","task-134","task-135","task-136"],"discoveries":["discovery-034"],"poly":"978,190 964,217 924,233 876,233 836,217 817,190 838,164 875,145 922,151 962,164","center":[900,190],"journal":"Исследованы «Моря, реки и озёра». Реки России текут в бассейны трёх океанов и внутренних водоёмов; режим рек зависит от климата и направления течения."},{"id":"sector-35","name":"Природные зоны","type":"zones","tint":"#9fd0a0","chapter":3,"description":"Сканер выделяет широтные полосы растительности: от ледяных пустынь на севере до степей на юге. Нужно сопоставить зоны с почвами и животными.","geo":"Природно-хозяйственные зоны, почвы, растительный и животный мир.","requires":["sector-32","sector-34"],"taskIds":["task-137","task-138","task-139","task-140"],"discoveries":["discovery-035"],"poly":"835,320 827,350 784,366 737,365 695,349 680,320 696,291 735,273 784,275 822,292","center":[760,320],"journal":"Исследованы «Природные зоны». Зоны сменяются с севера на юг; чем больше тепла и влаги, тем разнообразнее жизнь, но плодородие почв зависит от многих условий."},{"id":"sector-36","name":"Опасные явления и охрана","type":"hazards","tint":"#e0907a","chapter":3,"description":"Приборы фиксируют землетрясения, наводнения, ураганы. Нужно понять, где они вероятны и как защитить людей и природу.","geo":"Опасные природные явления, безопасность, особо охраняемые природные территории.","requires":["sector-35"],"taskIds":["task-141","task-142","task-143","task-144"],"discoveries":["discovery-036"],"poly":"506,450 487,479 446,498 393,499 358,477 338,450 350,420 393,401 445,404 480,424","center":[420,450],"journal":"Исследованы «Опасные явления и охрана». Опасные явления распространены неравномерно; знание закономерностей помогает защититься, а заповедники сохраняют природу."},{"id":"sector-37","name":"Численность населения","type":"pop_ru","tint":"#d9b0c8","chapter":3,"description":"Перепись показывает, сколько людей живёт в стране и как меняется их число. Нужно разобраться в рождаемости, смертности и миграциях.","geo":"Численность населения, естественное и механическое движение.","requires":["sector-36"],"taskIds":["task-145","task-146","task-147","task-148"],"discoveries":["discovery-037"],"poly":"687,450 660,476 622,491 573,500 539,476 526,450 533,421 576,406 627,401 661,423","center":[600,450],"journal":"Исследована «Численность населения». Число жителей меняется из-за рождаемости, смертности и миграций, а в разных регионах эти показатели сильно различаются."},{"id":"sector-38","name":"Расселение и города","type":"settle","tint":"#e0c0a0","chapter":3,"description":"Ночные снимки страны показывают густую сеть огней на западе и редкие огоньки на востоке. Нужно объяснить такое размещение людей.","geo":"Плотность населения, основная полоса расселения, городское и сельское население.","requires":["sector-37"],"taskIds":["task-149","task-150","task-151","task-152"],"discoveries":["discovery-038"],"poly":"863,450 849,480 803,493 753,500 719,476 697,450 721,424 754,402 803,408 847,421","center":[780,450],"journal":"Исследованы «Расселение и города». Россия очень неравномерно заселена: большинство людей живёт в городах, на западе и юге страны."},{"id":"sector-39","name":"Народы и религии","type":"peoples_ru","tint":"#c8c090","chapter":3,"description":"Языки, обычаи и вера разных народов России нанесены на карту. Нужно понять, как они распределены по территории.","geo":"Этнический и религиозный состав населения.","requires":["sector-37"],"taskIds":["task-153","task-154","task-155","task-156"],"discoveries":["discovery-039"],"poly":"1034,320 1011,348 973,365 925,369 891,347 866,320 882,289 928,277 976,271 1015,291","center":[950,320],"journal":"Исследованы «Народы и религии». В России живёт более 190 народов; традиционные религии распределены по регионам неравномерно."},{"id":"sector-40","name":"Человеческий капитал","type":"capital","tint":"#9fd6c4","chapter":3,"description":"Последний пакет данных: возрастной состав и рынок труда. Он показывает, какими силами располагает страна для развития.","geo":"Половозрастная структура, трудовые ресурсы, рынок труда.","requires":["sector-38","sector-39"],"taskIds":["task-157","task-158","task-159","task-160"],"discoveries":["discovery-040"],"poly":"1032,450 1018,476 985,497 937,493 902,476 883,450 898,422 937,407 984,405 1027,420","center":[960,450],"journal":"Исследован «Человеческий капитал». Развитие страны зависит от возрастного состава населения, количества и качества трудовых ресурсов."}],"tasks":[{"id":"task-105","sectorId":"sector-27","type":"multiple_choice","topic":"history","title":"Плавание вокруг Чукотки","description":"В 1648 году русские мореходы на кочах отправились от устья Колымы на восток. Они обогнули северо-восточную оконечность Азии и прошли между Азией и Северной Америкой, но об этом долго никто не знал.","question":"Кто возглавил это плавание?","hint":"Его имя носит самая восточная точка материковой России — мыс на Чукотке.","explanation":"Это Семён Дежнёв. Его экспедиция в 1648 году первой прошла пролив между Азией и Америкой. Позднее, в 1728 году, этот пролив повторно прошёл Витус Беринг, и пролив назвали его именем.","extra":false,"complex":false,"fgos":"1.1.1","options":["Семён Дежнёв","Ермак Тимофеевич","Ерофей Хабаров","Владимир Атласов"],"correctAnswer":0},{"id":"task-106","sectorId":"sector-27","type":"map_click","topic":"history","title":"Поход за Урал","description":"В 1581–1582 годах отряд казаков под командованием Ермака перешёл Урал и разгромил войско хана Кучума. Так началось присоединение Сибири к России. На схеме показано движение с запада на восток.","question":"Нажми на область, куда пришёл отряд Ермака и где располагалось ханство Кучума.","hint":"Ермак перешёл Уральские горы. Какая область лежит сразу за Уралом?","explanation":"Сибирское ханство Кучума находилось в Западной Сибири, за Уралом. После похода Ермака сюда пошли новые отряды, строились остроги (Тюмень, Тобольск). Дальше на восток, к Тихому океану, землепроходцы дошли к середине XVII века.","extra":false,"complex":false,"fgos":"1.1.1","correctZone":"wsib","diagram":{"viewBox":"0 0 300 180","compass":false,"items":[{"t":"rect","x":0,"y":0,"w":300,"h":180,"c":"card"},{"t":"zone","id":"moscow","label":"Московская Русь","x":6,"y":20,"w":68,"h":140,"c":"forest"},{"t":"zone","id":"volga","label":"Поволжье","x":78,"y":20,"w":68,"h":140,"c":"steppe"},{"t":"zone","id":"wsib","label":"Западная Сибирь","x":150,"y":20,"w":68,"h":140,"c":"taiga"},{"t":"zone","id":"esib","label":"Восточная Сибирь, Дальний Восток","x":222,"y":20,"w":72,"h":140,"c":"tundra"},{"t":"text","x":150,"y":12,"s":"С запада на восток","sm":true}]}},{"id":"task-107","sectorId":"sector-27","type":"analysis","topic":"history","title":"Таблица изменений границ","description":"Исследователь составляет таблицу: в ней события, которые меняли территорию России. Нужно найти то, что привело не к расширению, а к уменьшению государственной территории.","question":"Какое из событий привело к уменьшению территории России?","hint":"Определи, какое событие связано с передачей земель другому государству.","explanation":"В 1867 году Россия продала Аляску Соединённым Штатам. Остальные события расширили территорию: Ништадтский мир (1721) вернул выход к Балтике, присоединение Крыма (1783) — выход к Чёрному морю, поход Ермака (1581–1582) открыл путь в Сибирь.","extra":false,"complex":true,"fgos":"1.1.3","options":["Продажа Аляски США (1867)","Присоединение Крыма (1783)","Ништадтский мир со Швецией (1721)","Поход Ермака в Сибирь (1581–1582)"],"correctAnswer":0,"diagram":{"viewBox":"0 0 300 180","compass":false,"items":[{"t":"rect","x":0,"y":0,"w":300,"h":180,"c":"card"},{"t":"text","x":150,"y":16,"s":"Изменения границ России","sm":true},{"t":"text","x":150,"y":48,"s":"1581–1582 — поход Ермака в Сибирь","sm":true},{"t":"text","x":150,"y":78,"s":"1721 — Ништадтский мир: выход к Балтике","sm":true},{"t":"text","x":150,"y":108,"s":"1783 — присоединение Крыма","sm":true},{"t":"text","x":150,"y":138,"s":"1867 — Аляска передана США","sm":true}]}},{"id":"task-108","sectorId":"sector-27","type":"identify","topic":"history","title":"Описатель Камчатки","description":"Это российский учёный XVIII века, участник Второй Камчатской экспедиции. Он изучал полуостров четыре года и написал «Описание земли Камчатки» (1755) — первый научный труд об этом крае.","question":"Как зовут этого учёного?","hint":"Он был учеником академика, участвовал в экспедиции Витуса Беринга, но не был мореплавателем.","explanation":"Это Степан Крашенинников. Его книга описала природу, народы и хозяйство Камчатки. Вклад российских учёных и путешественников в изучение территории страны огромен: от землепроходцев XVII века до академических экспедиций XVIII–XIX веков.","extra":true,"complex":false,"fgos":"1.1.2","options":["Степан Крашенинников","Пётр Семёнов-Тян-Шанский","Николай Пржевальский","Николай Миклухо-Маклай"],"correctAnswer":0},{"id":"task-109","sectorId":"sector-28","type":"multiple_choice","topic":"borders","title":"Крайняя северная точка материка","description":"На карте России отмечают крайние точки материковой части: северную, южную, западную и восточную.","question":"Как называется самая северная точка материковой России?","hint":"Эта точка расположена на полуострове Таймыр, её название связано с именем полярного исследователя XVIII века.","explanation":"Самая северная точка материковой России — мыс Челюскин на полуострове Таймыр (около 77°43′ с. ш.). Восточная материковая точка — мыс Дежнёва, западная — на Балтийской косе в Калининградской области.","extra":false,"complex":false,"fgos":"1.2.1","options":["Мыс Челюскин","Мыс Дежнёва","Мыс Лопатка","Гора Базардюзю"],"correctAnswer":0},{"id":"task-110","sectorId":"sector-28","type":"map_click","topic":"borders","title":"Морские зоны","description":"На схеме показано море у берега России. Различают территориальное море (до 12 морских миль от берега), исключительную экономическую зону (до 200 морских миль) и открытое море.","question":"Нажми на зону, где Россия имеет исключительное право добывать рыбу, нефть и газ, а суда других стран могут свободно плавать.","hint":"Это не территориальное море (там полный суверенитет страны) и не открытое море (там права государства ограничены).","explanation":"В исключительной экономической зоне (ИЭЗ, до 200 морских миль) государство имеет суверенные права на разведку и добычу природных ресурсов; иностранные суда могут проходить свободно. В территориальных водах действуют законы России, а континентальный шельф связан с недрами морского дна.","extra":false,"complex":false,"fgos":"1.2.5","correctZone":"eez","diagram":{"viewBox":"0 0 300 180","compass":false,"items":[{"t":"rect","x":0,"y":0,"w":300,"h":28,"c":"land"},{"t":"text","x":150,"y":18,"s":"Берег России","sm":true},{"t":"zone","id":"tw","label":"Территориальное море: до 12 морских миль от берега","x":4,"y":32,"w":292,"h":40,"c":"water"},{"t":"zone","id":"eez","label":"Исключительная экономическая зона: до 200 морских миль","x":4,"y":76,"w":292,"h":46,"c":"water"},{"t":"zone","id":"open","label":"Открытое море: дальше 200 морских миль","x":4,"y":126,"w":292,"h":48,"c":"water"}]}},{"id":"task-111","sectorId":"sector-28","type":"analysis","topic":"borders","title":"Выход к морю","description":"Россия омывается 12 морями трёх океанов: Северного Ледовитого, Тихого и Атлантического. Больше всего морских границ приходится на север страны, но арктические моря большую часть года покрыты льдом. Выход к незамерзающим портам есть на западе (Балтийское, Чёрное моря) и юго-востоке (Японское море).","question":"Как положение России влияет на использование морей для торговли?","hint":"Подумай, как лёд влияет на судоходство и какие порты работают круглый год.","explanation":"Из-за льдов на Северном морском пути требуются ледоколы, а для круглогодичной торговли важны незамерзающие порты: Мурманск (тёплое Северо-Атлантическое течение), Новороссийск, Санкт-Петербург (с ледокольной проводкой), Владивосток. Это пример влияния географического положения на хозяйство.","extra":false,"complex":true,"fgos":"1.2.4","options":["Арктические моря покрыты льдом большую часть года, поэтому нужны ледоколы и незамерзающие порты","Все порты России работают круглый год без ограничений","Моря России почти не используются для торговли","Арктические моря самые тёплые, поэтому там проходят основные торговые пути"],"correctAnswer":0},{"id":"task-112","sectorId":"sector-28","type":"identify","topic":"borders","title":"Самая длинная граница","description":"Россия граничит с 14 государствами, больше, чем любая другая страна мира. С одним из соседей граница протянулась на 7,5 тысячи километров — это самая длинная сухопутная граница в мире.","question":"С какой страной у России самая длинная сухопутная граница?","hint":"Этот сосед находится на юге, в Азии, и когда-то входил в состав СССР.","explanation":"Самая длинная граница России — с Казахстаном (около 7,5 тыс. км). Другие соседи: Китай, Монголия, Финляндия, Норвегия, Эстония, Латвия, Литва, Польша, Белоруссия, Украина, Грузия, Азербайджан, КНДР.","extra":true,"complex":false,"fgos":"1.2.2","options":["Казахстан","Китай","Монголия","Финляндия"],"correctAnswer":0},{"id":"task-113","sectorId":"sector-29","type":"multiple_choice","topic":"timezones","title":"Сколько часовых зон","description":"Россия протянулась с запада на восток почти на 10 тысяч километров. Время в разных городах страны отличается: от Калининграда (UTC+2) до Камчатки (UTC+12).","question":"Сколько часовых зон на территории России?","hint":"Посчитай, сколько целых часовых смещений от UTC+2 до UTC+12 включительно.","explanation":"В России 11 часовых зон: от UTC+2 (Калининград) до UTC+12 (Камчатка, Чукотка). Разница между крайними зонами — 10 часов. Москва находится в зоне UTC+3, это московское время.","extra":false,"complex":false,"fgos":"1.3.1","options":["11","9","7","13"],"correctAnswer":0},{"id":"task-114","sectorId":"sector-29","type":"map_click","topic":"timezones","title":"Который час","description":"На схеме города России и их часовые зоны: Калининград (UTC+2), Москва (UTC+3), Екатеринбург (UTC+5), Новосибирск (UTC+7), Владивосток (UTC+10), Анадырь (UTC+12).","question":"В Москве 12:00. Нажми на город, где в этот момент 19:00.","hint":"Найди разницу во времени: 19 − 12 = 7 часов вперёд относительно Москвы.","explanation":"Москва — UTC+3, значит искомый город в зоне UTC+3+7 = UTC+10. Это Владивосток. Чем восточнее, тем время «впереди»: Земля вращается с запада на восток, и Солнце встаёт на востоке раньше.","extra":false,"complex":false,"fgos":"1.3.1","correctZone":"vl","diagram":{"viewBox":"0 0 300 180","compass":false,"items":[{"t":"rect","x":0,"y":0,"w":300,"h":180,"c":"card"},{"t":"zone","id":"kal","label":"Калининград UTC+2","x":6,"y":6,"w":144,"h":52,"c":"card"},{"t":"zone","id":"msk","label":"Москва UTC+3","x":154,"y":6,"w":140,"h":52,"c":"card"},{"t":"zone","id":"ekb","label":"Екатеринбург UTC+5","x":6,"y":64,"w":144,"h":52,"c":"card"},{"t":"zone","id":"nsk","label":"Новосибирск UTC+7","x":154,"y":64,"w":140,"h":52,"c":"card"},{"t":"zone","id":"vl","label":"Владивосток UTC+10","x":6,"y":122,"w":144,"h":52,"c":"card"},{"t":"zone","id":"pk","label":"Анадырь UTC+12","x":154,"y":122,"w":140,"h":52,"c":"card"}]}},{"id":"task-115","sectorId":"sector-29","type":"analysis","topic":"timezones","title":"Расписание рейса","description":"Самолёт вылетает из Москвы в 08:00 по московскому времени. Полёт до Новосибирска длится 4 часа. Время в Новосибирске опережает московское на 4 часа.","question":"Во сколько самолёт прилетит в Новосибирск по местному времени?","hint":"Сначала найди время прибытия по московскому времени, затем добавь разницу часовых зон.","explanation":"По московскому времени самолёт прилетит в 08:00 + 4 ч = 12:00. В Новосибирске время на 4 часа больше: 12:00 + 4 ч = 16:00 по местному времени.","extra":false,"complex":true,"fgos":"1.3.1","options":["16:00","12:00","20:00","08:00"],"correctAnswer":0,"diagram":{"viewBox":"0 0 300 180","compass":false,"items":[{"t":"rect","x":0,"y":0,"w":300,"h":180,"c":"card"},{"t":"text","x":150,"y":24,"s":"Москва: вылет 08:00 (UTC+3)","sm":true},{"t":"text","x":150,"y":58,"s":"Время в пути: 4 часа","sm":true},{"t":"text","x":150,"y":92,"s":"Новосибирск: UTC+7","sm":true},{"t":"text","x":150,"y":126,"s":"Разница с Москвой: +4 часа","sm":true}]}},{"id":"task-116","sectorId":"sector-29","type":"identify","topic":"timezones","title":"Какое время","description":"Время, определяемое по положению Солнца на конкретном меридиане: когда Солнце в верхней точке над горизонтом, в этом месте полдень.","question":"Как называют такое время?","hint":"Название связано с одним конкретным местом, а не с широкой полосой.","explanation":"Это местное время. Оно различается даже между близкими городами. Поясное время общее для всего пояса (около 15° по долготе), а зональное время устанавливается законом для территории часовой зоны.","extra":true,"complex":false,"fgos":"1.3.1","options":["Местное время","Поясное время","Зональное время","Всемирное время (UTC)"],"correctAnswer":0},{"id":"task-117","sectorId":"sector-30","type":"multiple_choice","topic":"regions","title":"Виды субъектов","description":"В состав Российской Федерации входят субъекты нескольких видов: республики, края, области, города федерального значения, автономная область и автономные округа. Все они равноправны.","question":"Какой из перечисленных субъектов является республикой?","hint":"В названии республики нет слов «край», «область» и «округ».","explanation":"Татарстан — республика. Красноярский край — край, Свердловская область — область, Ямало-Ненецкий автономный округ — автономный округ. У республик есть собственные конституции и государственные языки наряду с русским.","extra":false,"complex":false,"fgos":"1.2.3","options":["Татарстан","Красноярский край","Свердловская область","Ямало-Ненецкий автономный округ"],"correctAnswer":0},{"id":"task-118","sectorId":"sector-30","type":"map_click","topic":"regions","title":"Федеральные округа","description":"Для управления страной субъекты объединены в федеральные округа. На схеме показаны некоторые из них. В один из округов входят Свердловская и Челябинская области, а также Ханты-Мансийский и Ямало-Ненецкий автономные округа.","question":"Нажми на федеральный округ, в который входят эти субъекты.","hint":"Эти субъекты расположены вдоль Уральских гор и в Западной Сибири.","explanation":"Это Уральский федеральный округ. Он включает Свердловскую, Челябинскую, Тюменскую и Курганскую области, а также ХМАО и ЯНАО. В России восемь федеральных округов, самый большой по площади — Дальневосточный.","extra":false,"complex":false,"fgos":"1.4.1","correctZone":"ural","diagram":{"viewBox":"0 0 300 180","compass":false,"items":[{"t":"rect","x":0,"y":0,"w":300,"h":180,"c":"card"},{"t":"zone","id":"sz","label":"Северо-Западный","x":6,"y":6,"w":144,"h":52,"c":"forest"},{"t":"zone","id":"cfo","label":"Центральный","x":154,"y":6,"w":140,"h":52,"c":"steppe"},{"t":"zone","id":"pfo","label":"Приволжский","x":6,"y":64,"w":144,"h":52,"c":"low"},{"t":"zone","id":"ural","label":"Уральский","x":154,"y":64,"w":140,"h":52,"c":"mount"},{"t":"zone","id":"sfo","label":"Сибирский","x":6,"y":122,"w":144,"h":52,"c":"taiga"},{"t":"zone","id":"dfo","label":"Дальневосточный","x":154,"y":122,"w":140,"h":52,"c":"tundra"}]}},{"id":"task-119","sectorId":"sector-30","type":"analysis","topic":"regions","title":"Огромный регион","description":"Республика Саха (Якутия) — самый большой по площади субъект РФ: 3,08 млн км². Площадь всей России — 17,1 млн км². На схеме длина верхней полосы соответствует площади страны.","question":"Какую долю территории России занимает Якутия?","hint":"Раздели 3,08 на 17,1 и округли.","explanation":"3,08 ÷ 17,1 ≈ 0,18, то есть около 18 %, почти пятая часть страны. Субъекты РФ очень различаются: Москва занимает лишь около 2,5 тыс. км², то есть в тысячи раз меньше.","extra":false,"complex":true,"fgos":"1.2.3","options":["Около 18 %","Около 5 %","Около 40 %","Около 1 %"],"correctAnswer":0,"diagram":{"viewBox":"0 0 300 180","compass":false,"items":[{"t":"rect","x":0,"y":0,"w":300,"h":180,"c":"card"},{"t":"rect","x":30,"y":50,"w":240,"h":26,"c":"land"},{"t":"text","x":150,"y":68,"s":"Россия: 17,1 млн км²","sm":true},{"t":"rect","x":30,"y":100,"w":43,"h":26,"c":"bar"},{"t":"text","x":82,"y":118,"s":"Якутия: 3,08 млн км²","a":"start","sm":true}]}},{"id":"task-120","sectorId":"sector-30","type":"identify","topic":"regions","title":"Город федерального значения","description":"Этот город основан в 1703 году, стоит на реке Неве у Финского залива. Он является самостоятельным субъектом Российской Федерации — городом федерального значения.","question":"Как называется этот город?","hint":"Города федерального значения — Москва, Севастополь и ещё один город на северо-западе страны.","explanation":"Это Санкт-Петербург. Город был основан Петром I как «окно в Европу» и долго был столицей империи. Сейчас он один из трёх городов федерального значения.","extra":true,"complex":false,"fgos":"1.2.3","options":["Санкт-Петербург","Москва","Калининград","Нижний Новгород"],"correctAnswer":0},{"id":"task-121","sectorId":"sector-31","type":"multiple_choice","topic":"resources","title":"Исчерпаемая нефть","description":"Нефть образуется в недрах миллионы лет. Человечество добывает её намного быстрее, чем она образуется.","question":"К какой группе по исчерпаемости относится нефть?","hint":"Подумай, восполняются ли запасы нефти за время человеческой жизни.","explanation":"Нефть — исчерпаемый невозобновимый ресурс: запасы ограничены, и они не восстанавливаются в обозримом будущем. Возобновимы леса, рыба, плодородие почв при разумном использовании. Неисчерпаемы энергия солнца, ветра, воды.","extra":false,"complex":false,"fgos":"2.1.2","options":["Исчерпаемый невозобновимый","Исчерпаемый возобновимый","Неисчерпаемый","Рекреационный"],"correctAnswer":0},{"id":"task-122","sectorId":"sector-31","type":"map_click","topic":"resources","title":"Ресурсная база","description":"Ресурсная база — территория, где сосредоточены крупные запасы определённых ресурсов. На схеме показаны четыре района.","question":"Нажми на район, где добывают основную часть российских нефти и природного газа.","hint":"Ищи обширную равнину к востоку от Уральских гор.","explanation":"Крупнейшая нефтегазовая база России — Западная Сибирь (ХМАО и ЯНАО). Здесь добывают большую часть российских нефти и газа. На Кольском полуострове добывают апатиты и никель, на Северном Кавказе — меньшие объёмы нефти, в Приморье — олово и другие руды.","extra":false,"complex":false,"fgos":"2.1.1","correctZone":"wsib","diagram":{"viewBox":"0 0 300 180","compass":false,"items":[{"t":"rect","x":0,"y":0,"w":300,"h":180,"c":"card"},{"t":"zone","id":"wsib","label":"Западная Сибирь","x":8,"y":8,"w":140,"h":76,"c":"taiga"},{"t":"zone","id":"kola","label":"Кольский полуостров","x":152,"y":8,"w":140,"h":76,"c":"tundra"},{"t":"zone","id":"nkav","label":"Северный Кавказ","x":8,"y":90,"w":140,"h":80,"c":"mount"},{"t":"zone","id":"prim","label":"Приморье","x":152,"y":90,"w":140,"h":80,"c":"forest"}]}},{"id":"task-123","sectorId":"sector-31","type":"analysis","topic":"resources","title":"Расточительное хозяйствование","description":"Разные организации используют природные ресурсы по-разному. Рациональное природопользование — использование ресурсов с минимальным ущербом и с учётом интересов будущих поколений.","question":"Какой из примеров относится к нерациональному природопользованию?","hint":"Нерациональное использование — когда ресурс используют неполно или тратят впустую.","explanation":"Сжигание попутного нефтяного газа в факелах без использования — нерациональное природопользование: ценное сырьё и энергия теряются, а в воздух выбрасываются загрязнения. Рациональные примеры: севооборот, квоты на вылов рыбы, переработка отходов.","extra":false,"complex":true,"fgos":"2.1.5","options":["Нефтяная компания сжигает попутный газ в факелах, не используя его","Рыбацкая артель вылавливает рыбу в пределах установленных квот","Фермерское хозяйство чередует культуры на полях (севооборот)","Город собирает макулатуру для переработки"],"correctAnswer":0},{"id":"task-124","sectorId":"sector-31","type":"identify","topic":"resources","title":"Лес как ресурс","description":"Лесное хозяйство региона ведёт вырубку, но после неё высаживает новые деревья и следит, чтобы вырубаемая площадь не превышала прирост леса.","question":"К какой группе по исчерпаемости относятся такие лесные ресурсы?","hint":"Подумай: при правильном хозяйствовании запас леса восстанавливается.","explanation":"Это исчерпаемые возобновимые ресурсы: лес можно использовать постоянно, если не вырубать больше, чем успевает вырасти.","extra":true,"complex":false,"fgos":"2.1.2","options":["Исчерпаемые возобновимые","Исчерпаемые невозобновимые","Неисчерпаемые","Не являются ресурсами"],"correctAnswer":0},{"id":"task-125","sectorId":"sector-32","type":"multiple_choice","topic":"geology","title":"Основание равнины","description":"Крупные равнины России расположены на платформах — устойчивых участках земной коры. Фундамент платформы сложен древними кристаллическими породами, сверху лежит осадочный чехол.","question":"На какой платформе расположена Восточно-Европейская (Русская) равнина?","hint":"Название платформы совпадает с названием равнины.","explanation":"Русская равнина лежит на Восточно-Европейской платформе. Западно-Сибирская равнина — на молодой Западно-Сибирской плите, Среднесибирское плоскогорье — на Сибирской платформе.","extra":false,"complex":false,"fgos":"2.2.3","options":["Восточно-Европейская платформа","Сибирская платформа","Западно-Сибирская плита","Тихоокеанская плита"],"correctAnswer":0},{"id":"task-126","sectorId":"sector-32","type":"map_click","topic":"geology","title":"Огненный край России","description":"Земная кора вдоль границ литосферных плит подвижна. В России одна из самых активных зон лежит на востоке, где Тихоокеанская плита погружается под Евразию.","question":"Нажми на область, где находятся действующие вулканы и часты сильные землетрясения.","hint":"Это край страны, омываемый Тихим океаном.","explanation":"На Камчатке и Курильских островах находятся десятки действующих вулканов (Ключевская Сопка — самый высокий действующий вулкан Евразии, 4750 м). Русская равнина и Урал далеки от границ плит, здесь землетрясения редки и слабые.","extra":false,"complex":false,"fgos":"2.2.5","correctZone":"kam","diagram":{"viewBox":"0 0 300 180","compass":false,"items":[{"t":"rect","x":0,"y":0,"w":300,"h":180,"c":"card"},{"t":"zone","id":"rus","label":"Русская равнина","x":8,"y":20,"w":85,"h":140,"c":"low"},{"t":"zone","id":"ural","label":"Урал","x":97,"y":20,"w":60,"h":140,"c":"hill"},{"t":"zone","id":"kam","label":"Камчатка и Курилы","x":161,"y":20,"w":131,"h":140,"c":"mount"}]}},{"id":"task-127","sectorId":"sector-32","type":"analysis","topic":"geology","title":"Старые и молодые горы","description":"Уральские горы возникли около 300 млн лет назад, горы Памира — гораздо позже. Высочайшая вершина Урала — гора Народная (1895 м), высочайшая вершина Земли — Джомолунгма (8849 м). Старые горы разрушаются выветриванием уже сотни миллионов лет.","question":"Почему Урал значительно ниже молодых гор?","hint":"Сравни, сколько времени на Урале действует разрушение.","explanation":"Урал очень древний: за сотни миллионов лет горы были сильно разрушены выветриванием и водой, поэтому они невысокие со сглаженными вершинами. Молодые горные системы (Гималаи, Кавказ) ещё растут и мало разрушены.","extra":false,"complex":true,"fgos":"2.2.4","options":["Урал очень древний и сильно разрушен выветриванием","Урал образовался совсем недавно","Горы Урала лежат на дне океана","Урал находится на экваторе"],"correctAnswer":0,"diagram":{"viewBox":"0 0 300 180","compass":false,"items":[{"t":"rect","x":0,"y":0,"w":300,"h":180,"c":"card"},{"t":"rect","x":20,"y":150,"w":260,"h":4,"c":"land"},{"t":"rect","x":55,"y":122,"w":50,"h":28,"c":"mount"},{"t":"rect","x":195,"y":24,"w":50,"h":126,"c":"mount"},{"t":"text","x":80,"y":114,"s":"Урал: 1895 м","sm":true},{"t":"text","x":220,"y":16,"s":"Эверест: 8849 м","sm":true},{"t":"text","x":78,"y":172,"s":"около 300 млн лет","sm":true},{"t":"text","x":220,"y":172,"s":"около 50 млн лет","sm":true}]}},{"id":"task-128","sectorId":"sector-32","type":"identify","topic":"geology","title":"Дюна-полумесяц","description":"В пустынях и на песчаных берегах ветер создаёт особые формы рельефа: песчаные холмы в форме полумесяца, «рогами» направленные по ветру.","question":"Как называется такая форма?","hint":"Название пришло из тюркских языков и означает «песчаный холм».","explanation":"Это бархан. Бархан образуется под действием ветра. Дюны на берегу Балтики (Куршская коса) тоже созданы ветром, но у них иная форма. В России барханы встречаются в Прикаспии и Калмыкии.","extra":true,"complex":false,"fgos":"2.2.6","options":["Бархан","Морена","Овраг","Карстовая воронка"],"correctAnswer":0},{"id":"task-129","sectorId":"sector-33","type":"multiple_choice","topic":"climate_ru","title":"Амплитуда температур","description":"В Якутии в январе средняя температура около −40 °C, а в июле около +19 °C. Метеорологи говорят о годовой амплитуде температуры.","question":"Как найти годовую амплитуду температуры?","hint":"Это разность двух крайних значений.","explanation":"Годовая амплитуда — разность между средней температурой самого тёплого и самого холодного месяца: 19 − (−40) = 59 °C. Чем континентальнее климат, тем она больше.","extra":false,"complex":false,"fgos":"2.3.1","options":["Вычесть температуру самого холодного месяца из температуры самого тёплого","Сложить температуры января и июля","Разделить среднегодовую температуру на 12","Определить среднюю температуру за сутки"],"correctAnswer":0},{"id":"task-130","sectorId":"sector-33","type":"map_click","topic":"climate_ru","title":"Карта погоды","description":"На синоптической карте показаны два района. В районе А давление высокое, воздух опускается, облаков мало. В районе Б давление низкое, воздух поднимается, облака и осадки.","question":"Нажми на район, где установится ясная, сухая погода.","hint":"Опускающийся воздух нагревается и сушится, облака не образуются.","explanation":"В области высокого давления (антициклоне) воздух опускается, облаков мало, погода ясная. В циклоне воздух поднимается, образуются облака, идут осадки, ветер сильный.","extra":false,"complex":false,"fgos":"2.3.6","correctZone":"a","diagram":{"viewBox":"0 0 300 180","compass":false,"items":[{"t":"rect","x":0,"y":0,"w":300,"h":180,"c":"card"},{"t":"zone","id":"a","label":"Район А: давление высокое, воздух опускается","x":8,"y":20,"w":140,"h":140,"c":"card"},{"t":"zone","id":"b","label":"Район Б: давление низкое, воздух поднимается","x":152,"y":20,"w":140,"h":140,"c":"card"}]}},{"id":"task-131","sectorId":"sector-33","type":"analysis","topic":"climate_ru","title":"Коэффициент увлажнения","description":"Увлажнение территории оценивают коэффициентом увлажнения K = осадки ÷ испаряемость. В районе годовое количество осадков — 300 мм, а испаряемость — 600 мм.","question":"Как оценить увлажнение такой территории?","hint":"Вычисли K и сравни с единицей: при K < 1 влаги не хватает.","explanation":"K = 300 ÷ 600 = 0,5. Это меньше 1, значит, увлажнение недостаточное. Так бывает в степях и полупустынях Прикаспия. При K ≈ 1 — достаточное, при K > 1 — избыточное (тундра, тайга).","extra":false,"complex":true,"fgos":"2.3.3","options":["Недостаточное (K = 0,5)","Достаточное (K = 1)","Избыточное (K = 2)","Оценить нельзя"],"correctAnswer":0,"diagram":{"viewBox":"0 0 300 180","compass":false,"items":[{"t":"rect","x":0,"y":0,"w":300,"h":180,"c":"card"},{"t":"text","x":150,"y":36,"s":"Осадки: 300 мм в год","sm":true},{"t":"text","x":150,"y":70,"s":"Испаряемость: 600 мм в год","sm":true},{"t":"text","x":150,"y":104,"s":"K = осадки ÷ испаряемость","sm":true},{"t":"text","x":150,"y":140,"s":"K < 1 — влаги не хватает","sm":true}]}},{"id":"task-132","sectorId":"sector-33","type":"identify","topic":"climate_ru","title":"Ветры с океана","description":"На юге Дальнего Востока летом с океана дуют влажные ветры, зимой с суши — холодные и сухие. Из-за смены направления ветра осадки выпадают в основном летом.","question":"Как называется такой тип климата?","hint":"Название происходит от арабского слова, означающего «время года».","explanation":"Это муссонный климат. Он характерен для Приморья и юга Хабаровского края. Летние муссоны приносят ливни и наводнения, зимние — сухую холодную погоду.","extra":true,"complex":false,"fgos":"2.3.7","options":["Муссонный","Морской","Резко континентальный","Субтропический средиземноморский"],"correctAnswer":0},{"id":"task-133","sectorId":"sector-34","type":"multiple_choice","topic":"waters_ru","title":"Бассейн Атлантического океана","description":"Моря России принадлежат бассейнам трёх океанов: Северного Ледовитого, Тихого и Атлантического. К Атлантическому бассейну относят Балтийское, Чёрное и Азовское моря.","question":"Какое из названных морей относится к бассейну Атлантического океана?","hint":"Оно омывает юг европейской части страны и соединено с Мировым океаном через Босфор.","explanation":"Чёрное море относится к бассейну Атлантического океана (через Средиземное море). Охотское и Японское — бассейн Тихого, Карское — Северного Ледовитого.","extra":false,"complex":false,"fgos":"2.4.1","options":["Чёрное море","Охотское море","Карское море","Японское море"],"correctAnswer":0},{"id":"task-134","sectorId":"sector-34","type":"map_click","topic":"waters_ru","title":"Тихоокеанский бассейн","description":"На схеме показаны моря России. Одно из них — самое большое по площади из дальневосточных. Оно омывает Камчатку, Сахалин и Курильские острова.","question":"Нажми на море, которое относится к бассейну Тихого океана.","hint":"Из трёх морей на схеме два находятся на севере и западе страны.","explanation":"Охотское море — окраинное море Тихого океана; его воды омывают Камчатку и Сахалин. Баренцево море — Северный Ледовитый, Балтийское — Атлантический.","extra":false,"complex":false,"fgos":"2.4.1","correctZone":"ohot","diagram":{"viewBox":"0 0 300 180","compass":false,"items":[{"t":"rect","x":0,"y":0,"w":300,"h":180,"c":"card"},{"t":"zone","id":"bar","label":"Баренцево море","x":8,"y":20,"w":90,"h":140,"c":"water"},{"t":"zone","id":"balt","label":"Балтийское море","x":102,"y":20,"w":90,"h":140,"c":"water"},{"t":"zone","id":"ohot","label":"Охотское море","x":196,"y":20,"w":96,"h":140,"c":"water"}]}},{"id":"task-135","sectorId":"sector-34","type":"analysis","topic":"waters_ru","title":"Паводок на севере","description":"Река Лена течёт с юга на север, из тёплых районов в холодные. Весной лёд на её верховьях тает раньше, чем в низовьях, где ещё стоят морозы.","question":"К какому явлению это приводит в низовьях?","hint":"Вода из верховий идёт вниз, но лёд внизу ещё держится.","explanation":"Талая вода из верховий упирается в лёд низовьев и образует заторы — наводнения весной. Поэтому реки, текущие на север (Лена, Обь, Енисей), особенно подвержены весенним паводкам.","extra":false,"complex":true,"fgos":"2.4.3","options":["Ледовые заторы и сильное весеннее наводнение","Река полностью пересыхает","Река меняет направление течения","Вода становится солёной"],"correctAnswer":0,"diagram":{"viewBox":"0 0 300 180","compass":true,"items":[{"t":"rect","x":0,"y":0,"w":300,"h":180,"c":"card"},{"t":"arrow","x1":150,"y1":150,"x2":150,"y2":30,"label":"Лена течёт на север"},{"t":"text","x":6,"y":150,"s":"Верховья: лёд тает раньше","a":"start","sm":true},{"t":"text","x":6,"y":30,"s":"Низовья: ещё мороз","a":"start","sm":true}]}},{"id":"task-136","sectorId":"sector-34","type":"identify","topic":"waters_ru","title":"Самое большое озеро Европы","description":"Это озеро расположено на северо-западе страны, рядом с Санкт-Петербургом. Из него вытекает река Нева. Оно крупнейшее пресноводное озеро Европы.","question":"Как называется это озеро?","hint":"Название совпадает с одним из названий в Карелии.","explanation":"Это Ладожское озеро (площадь около 17,7 тыс. км²). Рядом находится Онежское озеро — второе по величине в Европе. Байкал — самое глубокое озеро мира.","extra":true,"complex":false,"fgos":"2.4.2","options":["Ладожское озеро","Онежское озеро","Байкал","Чудское озеро"],"correctAnswer":0},{"id":"task-137","sectorId":"sector-35","type":"multiple_choice","topic":"zones","title":"Плодородные почвы","description":"Чернозём — самая плодородная почва России. Он образуется там, где много перегноя: умеренно тёплый и достаточно влажный климат, богатая травянистая растительность.","question":"В какой природной зоне расположены основные чернозёмы?","hint":"Это зона между лесом и сухими степями Прикаспия.","explanation":"Чернозёмы типичны для лесостепи и степи. Здесь травы образуют много перегноя. В тундре почвы тонкие и холодные, в тайге — подзолистые, малоплодородные.","extra":false,"complex":false,"fgos":"2.5.3","options":["Лесостепь и степь","Тундра","Тайга","Арктические пустыни"],"correctAnswer":0},{"id":"task-138","sectorId":"sector-35","type":"map_click","topic":"zones","title":"Широтная зональность","description":"На схеме показаны природные зоны России с севера на юг. Одна из них — самая обширная: занимает около 60 % территории страны, простираясь от Балтики до Тихого океана.","question":"Нажми на самую большую по площади природную зону России.","hint":"Эта зона покрыта хвойными лесами: сосной, елью, лиственницей.","explanation":"Тайга — самая большая природная зона России (около 60 % территории). Здесь растут хвойные леса. Тундра, лесотундра, смешанные леса, лесостепь и степь занимают меньшие площади.","extra":false,"complex":false,"fgos":"2.5.1","correctZone":"taiga","diagram":{"viewBox":"0 0 300 180","compass":true,"items":[{"t":"rect","x":0,"y":0,"w":300,"h":180,"c":"card"},{"t":"zone","id":"tundra","label":"Тундра","x":8,"y":30,"w":284,"h":18,"c":"tundra"},{"t":"zone","id":"lt","label":"Лесотундра","x":8,"y":50,"w":284,"h":18,"c":"hill"},{"t":"zone","id":"taiga","label":"Хвойные леса","x":8,"y":70,"w":284,"h":40,"c":"taiga"},{"t":"zone","id":"mixed","label":"Смешанные леса","x":8,"y":112,"w":284,"h":18,"c":"forest"},{"t":"zone","id":"ls","label":"Лесостепь","x":8,"y":132,"w":284,"h":18,"c":"steppe"},{"t":"zone","id":"step","label":"Степь","x":8,"y":152,"w":284,"h":20,"c":"sand"}]}},{"id":"task-139","sectorId":"sector-35","type":"analysis","topic":"zones","title":"Разрез почвы","description":"На схеме показан разрез подзолистой почвы под хвойным лесом: сверху тонкий слой лесной подстилки, под ним светлый, бедный перегноем горизонт, ниже — более тёмный, потом материнская порода.","question":"Почему почвы тайги малоплодородны?","hint":"Подумай, сколько перегноя дают опавшая хвоя и холодный климат.","explanation":"Опавшая хвоя разлагается медленно из-за холода и кислая, поэтому перегноя образуется мало. Осадки вымывают питательные вещества вниз. Поэтому подзолистые почвы малоплодородны и для земледелия требуют удобрений.","extra":false,"complex":true,"fgos":"2.5.4","options":["Мало перегноя: хвоя разлагается медленно, а осадки вымывают вещества","Много перегноя из-за тёплого климата","Почвы состоят только из песка","В тайге почвы отсутствуют"],"correctAnswer":0,"diagram":{"viewBox":"0 0 300 180","compass":false,"items":[{"t":"rect","x":0,"y":0,"w":300,"h":180,"c":"card"},{"t":"zone","id":"a0","label":"Лесная подстилка","x":40,"y":14,"w":220,"h":24,"c":"forest"},{"t":"zone","id":"a1","label":"Светлый горизонт (мало перегноя)","x":40,"y":40,"w":220,"h":40,"c":"sand"},{"t":"zone","id":"a2","label":"Тёмный горизонт","x":40,"y":82,"w":220,"h":40,"c":"hill"},{"t":"zone","id":"a3","label":"Материнская порода","x":40,"y":124,"w":220,"h":44,"c":"land"}]}},{"id":"task-140","sectorId":"sector-35","type":"identify","topic":"zones","title":"Обитатель дальневосточной тайги","description":"Это самый крупный представитель семейства кошачьих в мире, обитающий в лесах Приморья и юга Хабаровского края. Занесён в Красную книгу.","question":"Как называется этот хищник?","hint":"На его шкуре тёмные полосы на оранжево-рыжем фоне.","explanation":"Это амурский (уссурийский) тигр. Его численность в России — около 500 особей. Защищается заповедниками и национальными парками, например «Земля леопарда».","extra":true,"complex":false,"fgos":"2.5.3","options":["Амурский тигр","Бурый медведь","Снежный барс","Рысь"],"correctAnswer":0},{"id":"task-141","sectorId":"sector-36","type":"multiple_choice","topic":"safety","title":"Вид стихийного бедствия","description":"Весной в долине реки вода вышла из берегов и затопила посёлки. Стихийные бедствия делят на группы по причинам: геологические, метеорологические, гидрологические и другие.","question":"К какой группе относится это бедствие?","hint":"Причина связана с водами рек.","explanation":"Наводнение — гидрологическое опасное явление. Землетрясения и извержения вулканов — геологические; ураганы, град — метеорологические; лесные пожары — биосферные.","extra":false,"complex":false,"fgos":"2.1.7","options":["Гидрологическое","Геологическое","Метеорологическое","Космическое"],"correctAnswer":0},{"id":"task-142","sectorId":"sector-36","type":"map_click","topic":"safety","title":"Риск цунами","description":"Цунами возникают при сильных подводных землетрясениях и извержениях. Они опасны для берегов, обращённых к зоне погружения плит.","question":"Нажми на побережье, где риск цунами в России наибольший.","hint":"Подумай, где проходит граница Тихоокеанской плиты рядом с нашей страной.","explanation":"Тихоокеанские берега Камчатки и Курильских островов — зона высокого риска цунами. Балтийское и Чёрное моря защищены от таких волн, а у Северного Ледовитого океана землетрясения слабее.","extra":false,"complex":false,"fgos":"2.1.7","correctZone":"pac","diagram":{"viewBox":"0 0 300 180","compass":false,"items":[{"t":"rect","x":0,"y":0,"w":300,"h":180,"c":"card"},{"t":"zone","id":"bal","label":"Балтийское побережье","x":8,"y":20,"w":90,"h":140,"c":"water"},{"t":"zone","id":"blk","label":"Чёрное море","x":102,"y":20,"w":90,"h":140,"c":"water"},{"t":"zone","id":"pac","label":"Тихоокеанское побережье","x":196,"y":20,"w":96,"h":140,"c":"water"}]}},{"id":"task-143","sectorId":"sector-36","type":"analysis","topic":"safety","title":"Как защититься","description":"Семья живёт в районе, где весной бывают наводнения. Нужно выбрать верный способ защиты.","question":"Какое решение самое разумное?","hint":"Лучшая защита — заранее знать риск и иметь план действий.","explanation":"Нужно знать план эвакуации, держать «тревожный чемоданчик», слушать прогнозы, не строить жильё в пойме. Попытка переждать воду на крыше или переправиться вброд опасна.","extra":false,"complex":true,"fgos":"2.5.5","options":["Заранее знать маршрут эвакуации, следить за прогнозами и не строить жильё в пойме","Игнорировать предупреждения МЧС","Построить дом прямо у воды","Пытаться пересечь поток вброд"],"correctAnswer":0},{"id":"task-144","sectorId":"sector-36","type":"identify","topic":"safety","title":"Охраняемая природа","description":"Это территория, где природа полностью охраняется: запрещены охота, рубка леса, строительство, а туристов почти не пускают. Здесь ведут научные наблюдения.","question":"Как называется такая особо охраняемая территория?","hint":"Первые такие территории в России появились ещё в 1916 году (Баргузинский).","explanation":"Это государственный природный заповедник. В национальных парках допускается ограниченный туризм, а в заказниках — частичная охрана отдельных объектов.","extra":true,"complex":false,"fgos":"2.5.7","options":["Заповедник","Национальный парк","Заказник","Памятник природы"],"correctAnswer":0},{"id":"task-145","sectorId":"sector-37","type":"multiple_choice","topic":"population_ru","title":"Естественный прирост","description":"Демографы следят за изменением числа жителей. Одна из главных характеристик — естественный прирост населения.","question":"Как рассчитывают естественный прирост?","hint":"В расчёте участвуют только рождения и смерти, миграции не учитываются.","explanation":"Естественный прирост = число родившихся − число умерших за год (обычно на 1000 жителей). Если умерших больше, чем родившихся, прирост отрицательный — это естественная убыль населения.","extra":false,"complex":false,"fgos":"3.1.6","options":["Число родившихся минус число умерших","Число прибывших минус число выбывших","Число родившихся плюс число умерших","Число жителей, делённое на площадь"],"correctAnswer":0},{"id":"task-146","sectorId":"sector-37","type":"map_click","topic":"population_ru","title":"Куда едут люди","description":"Механическое движение населения — это миграции. На схеме показаны четыре территории. Одна из них уже много лет принимает больше всего мигрантов из других регионов и стран, потому что там много рабочих мест.","question":"Нажми на территорию с самым большим миграционным притоком.","hint":"Там находится столица страны.","explanation":"Москва и Московская область — главный центр притяжения мигрантов: много рабочих мест, высокие доходы, развитая инфраструктура. Многие районы Дальнего Востока и Севера, наоборот, теряют жителей из-за оттока.","extra":false,"complex":false,"fgos":"3.1.5","correctZone":"msk","diagram":{"viewBox":"0 0 300 180","compass":false,"items":[{"t":"rect","x":0,"y":0,"w":300,"h":180,"c":"card"},{"t":"zone","id":"msk","label":"Москва и Московская область","x":8,"y":8,"w":140,"h":76,"c":"city"},{"t":"zone","id":"far","label":"Чукотка и Магаданская область","x":152,"y":8,"w":140,"h":76,"c":"tundra"},{"t":"zone","id":"ural","label":"Северный Урал","x":8,"y":90,"w":140,"h":80,"c":"mount"},{"t":"zone","id":"sib","label":"Северо-Восток Сибири","x":152,"y":90,"w":140,"h":80,"c":"taiga"}]}},{"id":"task-147","sectorId":"sector-37","type":"analysis","topic":"population_ru","title":"Баланс региона","description":"В регионе за год родились 18 тысяч человек, умерли 22 тысячи. Приехали на постоянное жительство 9 тысяч, уехали 4 тысячи.","question":"Как изменилась численность населения региона за год?","hint":"Сложи естественный прирост и миграционный прирост.","explanation":"Естественный прирост: 18 − 22 = −4 тыс. Миграционный: 9 − 4 = +5 тыс. Общий: −4 + 5 = +1 тыс. Население выросло на 1 тысячу за счёт миграции.","extra":false,"complex":true,"fgos":"3.1.3","options":["Выросла на 1 тысячу","Сократилась на 4 тысячи","Выросла на 5 тысяч","Не изменилась"],"correctAnswer":0,"diagram":{"viewBox":"0 0 300 180","compass":false,"items":[{"t":"rect","x":0,"y":0,"w":300,"h":180,"c":"card"},{"t":"text","x":150,"y":30,"s":"Родились: 18 тыс.   Умерли: 22 тыс.","sm":true},{"t":"text","x":150,"y":70,"s":"Приехали: 9 тыс.   Уехали: 4 тыс.","sm":true},{"t":"text","x":150,"y":120,"s":"Как изменилась численность?","sm":true}]}},{"id":"task-148","sectorId":"sector-37","type":"identify","topic":"population_ru","title":"Показатель рождаемости","description":"Это число родившихся за год на 1000 жителей. Его выражают в промилле (‰).","question":"Как называется этот показатель?","hint":"Он описывает только рождения, но не смерти и не миграции.","explanation":"Это коэффициент рождаемости. Смертность — число умерших на 1000 жителей. Разность между ними — естественный прирост.","extra":true,"complex":false,"fgos":"3.1.6","options":["Рождаемость","Смертность","Естественный прирост","Миграционный прирост"],"correctAnswer":0},{"id":"task-149","sectorId":"sector-38","type":"multiple_choice","topic":"settlement","title":"Где живут россияне","description":"Территория России очень велика, но население распределено неравномерно. Одна часть страны занимает меньшую площадь, но в ней живёт большинство жителей.","question":"Какая часть России наиболее заселена?","hint":"Подумай о климате и истории освоения территории.","explanation":"Примерно три четверти россиян живут в европейской части страны, которая занимает лишь около четверти территории. На Сибирь и Дальний Восток приходится заметно меньше жителей из-за сурового климата.","extra":false,"complex":false,"fgos":"3.2.3","options":["Европейская часть","Арктика","Восточная Сибирь","Чукотка"],"correctAnswer":0},{"id":"task-150","sectorId":"sector-38","type":"map_click","topic":"settlement","title":"Плотность населения","description":"Плотность населения — среднее число жителей на 1 км². На схеме показаны четыре территории.","question":"Нажми на территорию с самой низкой плотностью населения.","hint":"Там очень суровый климат, вечная мерзлота, мало дорог.","explanation":"На севере Восточной Сибири и Дальнего Востока (например, в Якутии) плотность составляет менее 1 человека на км². В Центральной России она в десятки раз выше, а в Москве — тысячи человек на км².","extra":false,"complex":false,"fgos":"3.2.2","correctZone":"yak","diagram":{"viewBox":"0 0 300 180","compass":false,"items":[{"t":"rect","x":0,"y":0,"w":300,"h":180,"c":"card"},{"t":"zone","id":"msk","label":"Москва","x":8,"y":8,"w":140,"h":76,"c":"city"},{"t":"zone","id":"kub","label":"Краснодарский край","x":152,"y":8,"w":140,"h":76,"c":"steppe"},{"t":"zone","id":"yak","label":"Север Якутии","x":8,"y":90,"w":140,"h":80,"c":"tundra"},{"t":"zone","id":"ural","label":"Свердловская область","x":152,"y":90,"w":140,"h":80,"c":"mount"}]}},{"id":"task-151","sectorId":"sector-38","type":"analysis","topic":"settlement","title":"Рост городов","description":"Доля городского населения России выросла с 52 % в 1959 году до 75 % в 2020 году. За это время сельское население стало заметно меньше.","question":"Как называется этот процесс?","hint":"Это рост роли городов и распространение городского образа жизни.","explanation":"Это урбанизация. В России она связана с индустриализацией и притоком людей в города из деревень. В мире доля горожан также растёт.","extra":false,"complex":true,"fgos":"3.2.4","options":["Урбанизация","Миграция","Депопуляция","Рождаемость"],"correctAnswer":0,"diagram":{"viewBox":"0 0 300 180","compass":false,"items":[{"t":"rect","x":0,"y":0,"w":300,"h":180,"c":"card"},{"t":"rect","x":40,"y":90,"w":70,"h":60,"c":"bar"},{"t":"text","x":75,"y":82,"s":"1959: 52 %","sm":true},{"t":"rect","x":190,"y":50,"w":70,"h":100,"c":"bar2"},{"t":"text","x":225,"y":42,"s":"2020: 75 %","sm":true},{"t":"line","pts":"30,150 270,150","c":"axis"},{"t":"text","x":150,"y":170,"s":"Доля городского населения","sm":true}]}},{"id":"task-152","sectorId":"sector-38","type":"identify","topic":"settlement","title":"Слившиеся города","description":"Крупный город и соседние города и посёлки так тесно связаны дорогами, работой и услугами, что образуют единую группу. Пример: Москва с городами Подмосковья.","question":"Как называется такая группа населённых пунктов?","hint":"Название включает слово «агломерация».","explanation":"Это городская агломерация. Крупнейшие агломерации России — Московская и Санкт-Петербургская. Агломерация — форма расселения, где города срастаются.","extra":true,"complex":false,"fgos":"3.1.4","options":["Городская агломерация","Сельское поселение","Мегаполис без пригородов","Посёлок городского типа"],"correctAnswer":0},{"id":"task-153","sectorId":"sector-39","type":"multiple_choice","topic":"peoples_ru","title":"Многонациональная страна","description":"В России живут люди более чем 190 национальностей. Самый многочисленный народ — русские. Второй по численности народ — на территории Поволжья и Урала.","question":"Какой народ второй по численности в России?","hint":"Этот народ проживает главным образом в Татарстане, Башкортостане и по всей стране.","explanation":"Татары — второй по численности народ России после русских. Республика Татарстан — их историческая родина. Далее по численности идут украинцы, башкиры, чуваши и другие.","extra":false,"complex":false,"fgos":"3.3.1","options":["Татары","Чуваши","Якуты","Буряты"],"correctAnswer":0},{"id":"task-154","sectorId":"sector-39","type":"map_click","topic":"peoples_ru","title":"Буддизм в России","description":"Основные религии России: православие (христианство), ислам, буддизм, иудаизм. Буддизм традиционен для народов юга Сибири.","question":"Нажми на регион, где традиционной религией является буддизм.","hint":"Подумай о районах рядом с Монголией и Китаем.","explanation":"Буддизм — традиционная религия бурят (Бурятия), калмыков (Калмыкия) и тувинцев (Тыва). Ислам распространён в Татарстане и на Северном Кавказе, православие — основная религия русских.","extra":false,"complex":false,"fgos":"3.3.1","correctZone":"bur","diagram":{"viewBox":"0 0 300 180","compass":false,"items":[{"t":"rect","x":0,"y":0,"w":300,"h":180,"c":"card"},{"t":"zone","id":"tat","label":"Татарстан","x":8,"y":8,"w":140,"h":76,"c":"steppe"},{"t":"zone","id":"bur","label":"Бурятия","x":152,"y":8,"w":140,"h":76,"c":"taiga"},{"t":"zone","id":"kar","label":"Карелия","x":8,"y":90,"w":140,"h":80,"c":"forest"},{"t":"zone","id":"dag","label":"Дагестан","x":152,"y":90,"w":140,"h":80,"c":"mount"}]}},{"id":"task-155","sectorId":"sector-39","type":"analysis","topic":"peoples_ru","title":"Состав населения","description":"По переписи, русские составляют около четырёх пятых населения, остальные — более 190 народов. В каждом регионе народы живут вперемешку, а некоторые республики имеют свой язык наряду с русским.","question":"Какой вывод можно сделать о России?","hint":"Учти и долю русских, и число других народов.","explanation":"Россия — многонациональное государство: русские составляют большинство, но страна является домом для множества народов с разными языками и традициями. Это важная особенность населения страны.","extra":false,"complex":true,"fgos":"3.3.1","options":["Россия — многонациональное государство с преобладанием русских","Россия — страна с одним народом","Нерусских народов почти нет","Все народы живут в одном регионе"],"correctAnswer":0},{"id":"task-156","sectorId":"sector-39","type":"identify","topic":"peoples_ru","title":"Самая распространённая религия","description":"Это одна из мировых религий, берущая начало от Иисуса Христа. В России её исповедует большинство верующих, прежде всего русские, а также украинцы и белорусы.","question":"Как называется направление христианства, наиболее распространённое в России?","hint":"Название связано со словами «правильно славить».","explanation":"Это православие. Другие религии: ислам, буддизм, иудаизм. Религиозное разнообразие — часть культурного наследия России.","extra":true,"complex":false,"fgos":"3.3.1","options":["Православие","Католицизм","Ислам","Буддизм"],"correctAnswer":0},{"id":"task-157","sectorId":"sector-40","type":"multiple_choice","topic":"capital","title":"Половозрастная пирамида","description":"Демографы показывают состав населения по полу и возрасту особым графиком: слева мужчины, справа женщины, по вертикали — возрастные группы.","question":"Как называется такой график?","hint":"Форма графика напоминает древние сооружения Египта.","explanation":"Это половозрастная пирамида. По её форме можно понять, молодое население или стареющее, и как менялась рождаемость.","extra":false,"complex":false,"fgos":"3.4.1","options":["Половозрастная пирамида","Климатограмма","Роза ветров","Профиль рельефа"],"correctAnswer":0},{"id":"task-158","sectorId":"sector-40","type":"map_click","topic":"capital","title":"Пирамида стареющей страны","description":"На схеме три половозрастные пирамиды. Широкое основание означает много детей. Узкое основание и расширенная середина или вершина — мало детей и много пожилых людей.","question":"Нажми на пирамиду, которая соответствует стареющему населению.","hint":"У стареющей страны в основании мало детей.","explanation":"Пирамида с узким основанием показывает низкую рождаемость и рост доли пожилых — это старение. Широкое основание типично для молодых стран с высокой рождаемостью.","extra":false,"complex":false,"fgos":"3.4.1","correctZone":"old","diagram":{"viewBox":"0 0 300 180","compass":false,"items":[{"t":"rect","x":0,"y":0,"w":300,"h":180,"c":"card"},{"t":"zone","id":"young","label":"Широкое основание","x":8,"y":20,"w":90,"h":140,"c":"city"},{"t":"zone","id":"mid","label":"Ровные стороны","x":102,"y":20,"w":90,"h":140,"c":"farm"},{"t":"zone","id":"old","label":"Узкое основание","x":196,"y":20,"w":96,"h":140,"c":"park"}]}},{"id":"task-159","sectorId":"sector-40","type":"analysis","topic":"capital","title":"Демографическая нагрузка","description":"В районе на каждую 1000 человек приходится 180 детей до 15 лет, 600 человек трудоспособного возраста и 220 человек старше трудоспособного возраста. Нагрузка на трудоспособных — число нетрудоспособных, приходящееся на 1000 трудоспособных.","question":"Чему равна демографическая нагрузка?","hint":"Нетрудоспособные — дети и пожилые вместе.","explanation":"(180 + 220) ÷ 600 × 1000 ≈ 667 человек на 1000 трудоспособных. Чем выше нагрузка, тем больше людей должны содержать работающие.","extra":false,"complex":true,"fgos":"3.5.1","options":["Около 667","Около 300","Около 400","Около 1000"],"correctAnswer":0,"diagram":{"viewBox":"0 0 300 180","compass":false,"items":[{"t":"rect","x":0,"y":0,"w":300,"h":180,"c":"card"},{"t":"text","x":150,"y":32,"s":"Дети до 15 лет: 180","sm":true},{"t":"text","x":150,"y":66,"s":"Трудоспособные: 600","sm":true},{"t":"text","x":150,"y":100,"s":"Старше трудоспособного: 220","sm":true},{"t":"text","x":150,"y":140,"s":"Нагрузка = нетрудоспособные ÷ трудоспособные","sm":true}]}},{"id":"task-160","sectorId":"sector-40","type":"identify","topic":"capital","title":"Безработица","description":"Это часть рабочей силы, которая не имеет работы, но ищет её и готова приступить к работе. Показатель выражают в процентах.","question":"Как называют такое явление?","hint":"Оно возникает, когда рабочих мест меньше, чем желающих работать.","explanation":"Это безработица. Рабочая сила — все занятые и безработные. Уровень безработицы в России в последние годы был низким, но сильно различается по регионам.","extra":true,"complex":false,"fgos":"3.5.1","options":["Безработица","Миграция","Урбанизация","Депопуляция"],"correctAnswer":0}],"discoveries":[{"id":"discovery-027","name":"Путь на восток","category":"История","short":"Территория России росла веками.","long":"Русские землепроходцы за XVI–XVII века прошли от Урала до Тихого океана: поход Ермака (1581–1582), плавание Дежнёва (1648).","sectors":["sector-27"],"condition":{"type":"sectorExplored","sector":"sector-27"}},{"id":"discovery-028","name":"Страна трёх океанов","category":"Положение","short":"Россия граничит с 14 странами и омывается морями трёх океанов.","long":"Моря Северного Ледовитого, Тихого и Атлантического океанов омывают страну; шельф и исключительная экономическая зона принадлежат России.","sectors":["sector-28"],"condition":{"type":"sectorExplored","sector":"sector-28"}},{"id":"discovery-029","name":"Одиннадцать часовых зон","category":"Время","short":"Между Калининградом и Камчаткой разница в 10 часов.","long":"В России действуют 11 часовых зон (от UTC+2 до UTC+12), поэтому время при перелётах и звонках нужно пересчитывать.","sectors":["sector-29"],"condition":{"type":"sectorExplored","sector":"sector-29"}},{"id":"discovery-030","name":"Федерация разных регионов","category":"Районирование","short":"Субъекты РФ разные по виду, размеру и населению.","long":"Республики, края, области, города федерального значения, автономная область и автономные округа различаются, но все равноправны.","sectors":["sector-30"],"condition":{"type":"sectorExplored","sector":"sector-30"}},{"id":"discovery-031","name":"Капитал природы","category":"Ресурсы","short":"Ресурсы бывают исчерпаемые и неисчерпаемые.","long":"Нефть и газ невозобновимы, леса и рыба возобновимы при разумном использовании, а энергия солнца и ветра неисчерпаема.","sectors":["sector-31"],"condition":{"type":"sectorExplored","sector":"sector-31"}},{"id":"discovery-032","name":"Платформы и горы России","category":"Рельеф","short":"Равнины лежат на платформах, горы — в складчатых областях.","long":"Восточно-Европейская равнина — на платформе, Урал — древние горы, а молодые горы и вулканы — на Камчатке и Курилах.","sectors":["sector-32"],"condition":{"type":"sectorExplored","sector":"sector-32"}},{"id":"discovery-033","name":"Циклоны, антициклоны и климат","category":"Климат","short":"Погоду определяют давление и воздушные массы.","long":"В циклонах пасмурно и бывают осадки, в антициклонах ясно; типы климата зависят от радиации, циркуляции и удалённости от океанов.","sectors":["sector-33"],"condition":{"type":"sectorExplored","sector":"sector-33"}},{"id":"discovery-034","name":"Реки, текущие на север","category":"Воды","short":"Большинство крупных рек Сибири впадает в Северный Ледовитый океан.","long":"Реки, текущие с юга на север, весной вскрываются в верховьях раньше, чем в низовьях, поэтому на них бывают заторы и наводнения.","sectors":["sector-34"],"condition":{"type":"sectorExplored","sector":"sector-34"}},{"id":"discovery-035","name":"Зоны и почвы","category":"Природные зоны","short":"Тайга — самая большая зона, лучшие почвы — чернозёмы.","long":"Зоны сменяются с севера на юг; почвы тайги бедны гумусом, а чернозёмы лесостепи и степи — самые плодородные.","sectors":["sector-35"],"condition":{"type":"sectorExplored","sector":"sector-35"}},{"id":"discovery-036","name":"Предупреждён — значит вооружён","category":"Безопасность","short":"Опасные явления можно предсказать и снизить ущерб.","long":"Знание районов опасных явлений, страхование и правила безопасности уменьшают ущерб, а заповедники сохраняют природу.","sectors":["sector-36"],"condition":{"type":"sectorExplored","sector":"sector-36"}},{"id":"discovery-037","name":"Формула прироста","category":"Население","short":"Общий прирост — это естественный прирост плюс миграционный.","long":"Естественный прирост равен рождаемости минус смертности; к нему добавляется миграционный прирост (приехавшие минус уехавшие).","sectors":["sector-37"],"condition":{"type":"sectorExplored","sector":"sector-37"}},{"id":"discovery-038","name":"Основная полоса расселения","category":"Население","short":"Люди живут неравномерно: больше на западе и юге.","long":"Около трёх четвертей населения живёт в европейской части страны; около трёх четвертей россиян — горожане.","sectors":["sector-38"],"condition":{"type":"sectorExplored","sector":"sector-38"}},{"id":"discovery-039","name":"Многонациональная страна","category":"Народы","short":"В России более 190 народов.","long":"Русские составляют большинство населения; многие народы живут в республиках; традиционные религии — православие, ислам, буддизм и другие.","sectors":["sector-39"],"condition":{"type":"sectorExplored","sector":"sector-39"}},{"id":"discovery-040","name":"Человеческий капитал России","category":"Население","short":"Возрастной состав влияет на рынок труда.","long":"Соотношение детей, трудоспособных и пожилых людей определяет нагрузку на экономику и потребность в рабочей силе.","sectors":["sector-40"],"condition":{"type":"sectorExplored","sector":"sector-40"}}],"achievements":[{"id":"c3-borders","chapter":3,"name":"Хранитель границ","description":"Исследованы границы и моря России.","condition":{"type":"sectorExplored","sector":"sector-28"}},{"id":"c3-time","chapter":3,"name":"Хранитель времени","description":"Освоены часовые пояса России.","condition":{"type":"sectorExplored","sector":"sector-29"}},{"id":"c3-first","chapter":3,"name":"Первые открытия России","description":"Найдено пять открытий главы 3.","condition":{"type":"discoveryCount","n":5}},{"id":"c3-geo","chapter":3,"name":"Геолог России","description":"Исследованы платформы и горы страны.","condition":{"type":"sectorExplored","sector":"sector-32"}},{"id":"c3-weather","chapter":3,"name":"Синоптик","description":"Решены три задачи о климате России.","condition":{"type":"topicTasks","topic":"climate_ru","n":3}},{"id":"c3-people","chapter":3,"name":"Демограф России","description":"Исследована численность населения.","condition":{"type":"sectorExplored","sector":"sector-37"}},{"id":"c3-full","chapter":3,"name":"Дотошный исследователь России","description":"Одна зона изучена полностью.","condition":{"type":"fullCount","n":1}},{"id":"c3-all","chapter":3,"name":"Вся Россия","description":"Исследованы все 14 зон карты России.","condition":{"type":"exploredCount","n":14}}]};
